args.value:
() => {
  const files = ['406_A1.png', '406_A2.png', '406_A3.png', '406_A4.png', '406_A5.png'];
  const results = [];
  for (const f of files) {
    const img = new Image();
    img.src = f;
    results.push(new Promise((resolve) => {
      img.onload = () => resolve({ file: f, width: img.naturalWidth, height: img.naturalHeight, ratio: (img.naturalWidth / img.naturalHeight).toFixed(2) });
      img.onerror = () => resolve({ file: f, error: true });
    }));
  }
  return Promise.all(results);
}

